import json
Hs = [(1, 4, 9), (2, 7, 3), (5, 4, 6), (6, 2, 9)]
t = 10
def vote(a):
    s = {}
    for i, ai, yi in Hs:
        if ai == a:
            s[yi] = s.get(yi, 0.0) + 1.0 / (t - i)
    return max(sorted(s), key=lambda v: s[v]), {str(k): round(v, 6) for k, v in sorted(s.items())}
best, scores = vote(4)
print(json.dumps({"answer": best, "scores": scores}))
